    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xC86CDBB085230277ULL + 0xE878B0A63B367047ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xDB89877A5E76CC09ULL + 0xBF29E62CF36B5D67ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0xC083C2A3361ED053ULL + 0x9BAFA5427C231752ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0x80A4B54BBD90E78DULL + 0xB4D63DAADA4D9955ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseC(pNonce * 0x83797AF6C1858BC3ULL + 0xC54C4652DC2F736CULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseB(pNonce * 0xA7A5252D5D13D44DULL + 0x9299A652F36E559CULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0xA606A09EEBBE8D35ULL + 0xC5732D4F3891486BULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseA(pNonce * 0x919BFDB7FCFE7965ULL + 0xFDC876735A4E4C33ULL);
