            aCross = RotL64(pSnow[((S_BLOCK1 - aIndex + 5089U)) & S_BLOCK1], 46U) ^ RotL64(aSource[((S_BLOCK1 - aIndex + 150U)) & S_BLOCK1], 13U);
            aCross = TwistMix64::DiffuseC(((aCross ^ aDomainWordCross) ^ aNonceWordG));
            //
            aScatter = (RotL64(aPrevious, 57U) + RotL64(aCross, 5U)) ^ (RotL64(aIngress, 35U) + RotL64(aCarry, 18U));
            aScatter = TwistMix64::DiffuseB(((aScatter ^ aDomainWordScatter) ^ aNonceWordB));
            //
            aOrbiterK = (aWandererG + RotL64(aScatter, 11U)) + 0x6C8B3649C79DE2D9ULL;
            aOrbiterA = (aWandererE + RotL64(aCross, 13U)) + 0xC92DABFB84A658BAULL;
            aOrbiterJ = (((aWandererB + RotL64(aIngress, 3U)) + 0xF1E39C28C66AB4A2ULL) + aOrbiterAssignSaltD[((aIndex + 3U)) & S_SALT1]) + aNonceWordA;
            aOrbiterH = (aWandererA + RotL64(aPrevious, 27U)) + 0x4BDE278A68F3E5A3ULL;
            aOrbiterB = ((aWandererD + RotL64(aScatter, 38U)) + 0xBC18280B7D34B9D3ULL) + aNonceWordN;
            aOrbiterF = ((aWandererC + RotL64(aIngress, 53U)) + 0x1726856C04BC2408ULL) + aNonceWordP;
            aOrbiterI = (aWandererF + RotL64(aPrevious, 47U)) + 0x4A7B6496462DB365ULL;
            aOrbiterD = ((aWandererK + RotL64(aCross, 43U)) + RotL64(aCarry, 35U)) + 0x51CA9815E76E5345ULL;
            aOrbiterG = ((aWandererJ + RotL64(aScatter, 29U)) + RotL64(aCarry, 53U)) + 0x1C31C6F0E470A2EAULL;
            aOrbiterE = (((aWandererH + RotL64(aPrevious, 40U)) + 0x598F1C634DC133BFULL) + aOrbiterAssignSaltF[((aIndex + 15U)) & S_SALT1]) + aNonceWordI;
            aOrbiterC = ((aWandererI + RotL64(aIngress, 23U)) + RotL64(aCarry, 19U)) + 0x86B6DE4EB9FC7056ULL;
