            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0xCFBB09C577597C16ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0x1AE1B761EDE66FCAULL) ^ aNonceWordC;
            aOrbiterH = RotL64((aOrbiterH * 0x0BC76C86422248F7ULL), 23U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0x4D40A2178B74957FULL) + aOrbiterUpdateSaltD[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0xDCA43D837F5C04B3ULL) ^ aOrbiterUpdateSaltB[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x37F4634AC96B9FDBULL), 11U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xA6B6657D5632628DULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterB) ^ 0x3D59712C75D7C386ULL) ^ aNonceWordB;
            aOrbiterF = RotL64((aOrbiterF * 0xDDAB91F0258F26DBULL), 43U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x8AC7301D20D2A215ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0xF4C7A767B497C2F4ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x0D856DE9E54ACCA1ULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x92E694B59A5F7382ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0xB822DA5030C5A1BFULL;
            aOrbiterI = RotL64((aOrbiterI * 0x2808E2EDF42B8DF3ULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xC1586DC3768D5EBCULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0x41860306EA33BD57ULL) ^ aOrbiterUpdateSaltA[((aIndex + 16U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xBF12894626433BE1ULL), 37U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0xCC7D3E3DEFACCB55ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0xEAC49AC42F177B33ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9521A09264FAF33DULL), 27U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0xCA32C0A83CC590B0ULL) + aNonceWordF;
            aOrbiterD = (((aOrbiterD ^ aOrbiterG) ^ 0xB13E0B5161ACCE77ULL) ^ aOrbiterUpdateSaltC[((aIndex + 7U)) & S_SALT1]) ^ aNonceWordD;
            aOrbiterD = RotL64((aOrbiterD * 0xCE44F4F7B182F465ULL), 53U);
            //
            aIngress = aOrbiterE ^ RotL64(aOrbiterF, 47U);
