            aIngress = aIngress + (RotL64(aOrbiterK, 29U) ^ aOrbiterJ);
            aIngress = aIngress + (RotL64(aOrbiterG, 3U) ^ aOrbiterD);
            aIngress = aIngress + RotL64(aOrbiterI, 60U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererC = aWandererC + (((RotL64(aCross, 34U) + RotL64(aOrbiterE, 5U)) + aOrbiterH) + RotL64(aCarry, 11U));
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 41U) + aOrbiterK) + RotL64(aOrbiterI, 53U));
            aWandererD = aWandererD + ((RotL64(aIngress, 13U) + aOrbiterE) + RotL64(aOrbiterJ, 57U));
            aWandererF = aWandererF ^ (((RotL64(aScatter, 19U) + aOrbiterA) + RotL64(aOrbiterD, 11U)) + aWandererUpdateSaltD[((aIndex + 4U)) & S_SALT1]);
            aWandererJ = aWandererJ + (((RotL64(aIngress, 27U) + aOrbiterK) + RotL64(aOrbiterB, 30U)) + aNonceWordM);
            aWandererG = aWandererG ^ (((RotL64(aPrevious, 11U) + aOrbiterE) + RotL64(aOrbiterC, 19U)) + aNonceWordK);
