            aOrbiterD = ((aWandererB + RotL64(aIngress, 29U)) + 0x0DD38672250D0CCAULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 13U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aScatter, 35U)) + RotL64(aCarry, 21U)) + 0x3A737A79F54BB0E0ULL;
            aOrbiterK = ((aWandererA + RotL64(aCross, 41U)) + 0x584763DFA780C719ULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
