            aOrbiterD = (((aWandererG + RotL64(aPrevious, 3U)) + RotL64(aCarry, 53U)) + 0xC732F27ADA717433ULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 17U)) & S_SALT1];
