            aOrbiterH = ((aWandererK + RotL64(aIngress, 41U)) + RotL64(aCarry, 27U)) + 0x1C1940CF82543EFEULL;
            aOrbiterF = (((aWandererC + RotL64(aScatter, 57U)) + RotL64(aCarry, 13U)) + 0x5272CF358D7A2735ULL) + aKeyRotateAOrbiterAssignSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
