            //
            aIngress = (RotL64(aAetherLaneA[((aIndex + 424U)) & S_BLOCK1], 21U) ^ RotL64(aAetherLaneB[((aIndex + 2829U)) & S_BLOCK1], 30U));
            aIngress ^= (RotL64(aWoodLaneB[((aIndex + 1467U)) & S_BLOCK1], 5U) ^ RotL64(aWaterLaneA[((aIndex + 3198U)) & S_BLOCK1], 43U));
